def ApproximableOn {n : ℕ} (h : FinitePoint n → Pair) (L : Set (FinitePoint n)) : Prop :=
  ∀ b : Bool, ∀ ε : ℝ, 0 < ε → ∃ p : MvPolynomial (Fin n) ℂ,
    ∀ z ∈ L, ‖MvPolynomial.eval z p - (if b then (h z).2 else (h z).1)‖ < ε

